SELECT FAQ_ID, QESTN_SJ, QESTN_CN, ANSWER_CN, RDCNT, ATCH_FILE_ID, TO_CHAR(FRST_REGIST_PNTTM,'YYYYmmdd') FRST_REGIST_PNTTM, FRST_REGISTER_ID, TO_CHAR(LAST_UPDT_PNTTM,'YYYYmmdd') LAST_UPDUSR_PNTTM, LAST_UPDUSR_ID FROM NFAQINFO WHERE 1=1
AND QESTN_SJ LIKE CONCAT('%', #{searchWrd}, '%')
ORDER BY FAQ_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

