			UPDATE	NFAQINFO	SET
				    RDCNT= COALESCE(RDCNT,0) + 1				  			
 			WHERE  FAQ_ID=#{faqId}


			UPDATE	NFAQINFO	SET
					FAQ_ID=#{faqId} 
				  , QESTN_SJ=#{qestnSj}
				  , QESTN_CN=#{qestnCn}
				  , ANSWER_CN=#{answerCn}
				  , ATCH_FILE_ID=#{atchFileId}				  			
				  , LAST_UPDT_PNTTM=NOW()
				  , LAST_UPDUSR_ID=#{lastUpdusrId}
 			WHERE  FAQ_ID=#{faqId}
